import{_ as t,o as l,c as o,S as i,h as e,s as a}from"./chunks/framework.D1Ss-Xl7.js";const m=JSON.parse('{"title":"Vue实现双Slider","description":"","frontmatter":{"title":"Vue实现双Slider","date":"2020-06-14 21:31","comments":true,"archives":2020,"tags":["frontend","vue"]},"headers":[],"relativePath":"posts/2020-06-14-vue-dual-slider/index.md","filePath":"posts/2020/2020-06-14-vue-dual-slider.md"}'),d={name:"posts/2020-06-14-vue-dual-slider/index.md"};function n(s,r,h,c,p,u){return l(),o("div",null,[...r[0]||(r[0]=[i('<p>前端由于历史原因，基本上没有组件的概念，原生的 HTML 元素提供的功能非常简陋，所以都需要开发者自己实现或者定制组件。这次讲讲双 Slider 的实现。</p><h2 id="技术选型" tabindex="-1">技术选型 <a class="header-anchor" href="#技术选型" aria-label="Permalink to &quot;技术选型&quot;">​</a></h2><p>目前比较流行的 Vue 的组件库是<a href="https://element.eleme.io/" target="_blank" rel="noreferrer">Element</a> 和 <a href="https://www.iviewui.com/" target="_blank" rel="noreferrer">View UI</a>。这两个组件库都使用了最常用的方法，使用<code>div</code>或者<code>span</code>，元素模拟滑动条，监听事件，并处理滑动。但是 HTML 元素本身提供了<a href="https://developer.mozilla.org/en-US/docs/Web/HTML/Element/input/range" target="_blank" rel="noreferrer">Range</a>标签，我们可以修改下样式来使用，这样就避免自己直接处理事件监听，也可以减少浏览器兼容性问题。</p><h2 id="样式定制化" tabindex="-1">样式定制化 <a class="header-anchor" href="#样式定制化" aria-label="Permalink to &quot;样式定制化&quot;">​</a></h2><p>目前针对 Range 元素的样式定制化还没有纳入 Web 标准，所以在处理起来稍微花点功夫。首先，我们需要修改默认的滑块样式。使用的 CSS 选择器是<a href="https://developer.mozilla.org/en-US/docs/Web/CSS/::-webkit-slider-thumb" target="_blank" rel="noreferrer">-webkit-slider-thumb</a>。由于未纳入标准，需要使用浏览器前缀才行。这里我们可以借助 <a href="https://github.com/jonathantneal/postcss-input-range" target="_blank" rel="noreferrer">postcss-input-range</a> 插件来完成这项工作。</p><h2 id="双-slider-实现" tabindex="-1">双 Slider 实现 <a class="header-anchor" href="#双-slider-实现" aria-label="Permalink to &quot;双 Slider 实现&quot;">​</a></h2><p>HTML 本身只提供了单滑块，要想实现双 Slider，只能两个叠加在一起了，并且需要自己实现 Slider 的选中范围，因为目前的 css selector 并不能达到这种效果。如何动态的控制 Slider 的显示长度呢？当然可以计算出目前的选中百分比，通过 css variables 来达到更新样式的效果。</p><h2 id="slider-滑动规则" tabindex="-1">Slider 滑动规则 <a class="header-anchor" href="#slider-滑动规则" aria-label="Permalink to &quot;Slider 滑动规则&quot;">​</a></h2><p>当然，我们左边的滑块不能滑过右边的滑块，这是基本常识。这里就需要监听<code>input</code> 事件，当超出范围的时候，强制把值重置回合法值就可以了。</p><h2 id="实现效果" tabindex="-1">实现效果 <a class="header-anchor" href="#实现效果" aria-label="Permalink to &quot;实现效果&quot;">​</a></h2>',10),e("iframe",{height:"325",style:{width:"100%"},scrolling:"no",title:"Slider",src:"https://codepen.io/acgotaku/embed/preview/LYGZQva?height=325&theme-id=dark&default-tab=js,result",frameborder:"no",allowtransparency:"true",allowfullscreen:"true"},[a(" See the Pen "),e("a",{href:"https://codepen.io/acgotaku/pen/LYGZQva"},"Slider"),a(" by 雪月秋水 ("),e("a",{href:"https://codepen.io/acgotaku"},"@acgotaku"),a(") on "),e("a",{href:"https://codepen.io"},"CodePen"),a(". ")],-1),e("h2",{id:"总结",tabindex:"-1"},[a("总结 "),e("a",{class:"header-anchor",href:"#总结","aria-label":'Permalink to "总结"'},"​")],-1),e("p",null,"能用原生 HTML 标签来解决的问题，尽量还是不要自己实现事件监听了。这样性能也会更好，兼容性上也不会太差。",-1)])])}const b=t(d,[["render",n]]);export{m as __pageData,b as default};
